/**
 * Test signals generated by code, so no audio file ever needs to be committed.
 * Imports use explicit .ts extensions so `node scripts/write-fixtures.ts` can run this
 * file directly.
 */
import { createRng } from '../../src/core/rng.ts';

export interface Signal {
  samples: Float32Array;
  sampleRate: number;
}

/** Exponential sine sweep from f0 to f1. */
export function sineSweep(sampleRate = 44100, seconds = 8, f0 = 100, f1 = 2000): Signal {
  const n = Math.round(seconds * sampleRate);
  const samples = new Float32Array(n);
  const k = Math.log(f1 / f0);
  for (let i = 0; i < n; i++) {
    const t = i / sampleRate;
    const phase = ((2 * Math.PI * f0 * seconds) / k) * (Math.exp((t / seconds) * k) - 1);
    samples[i] = 0.5 * Math.sin(phase);
  }
  return { samples, sampleRate };
}

/** Short noise clicks at a steady tempo. Returns the click times too. */
export function clickTrack(
  sampleRate = 44100,
  seconds = 8,
  bpm = 120,
  first = 0.25,
): Signal & { clicks: number[] } {
  const n = Math.round(seconds * sampleRate);
  const samples = new Float32Array(n);
  const rng = createRng(120);
  const clicks: number[] = [];
  const length = Math.round(0.004 * sampleRate);
  for (let t = first; t < seconds - 0.05; t += 60 / bpm) {
    clicks.push(t);
    const start = Math.round(t * sampleRate);
    for (let i = 0; i < length && start + i < n; i++) {
      const decay = Math.pow(1 - i / length, 2);
      samples[start + i] = 0.8 * decay * (rng.next() * 2 - 1);
    }
  }
  return { samples, sampleRate, clicks };
}

/** A low drone (55 Hz with two harmonics) with digital silence between gapStart and gapEnd. */
export function droneWithGap(sampleRate = 44100, seconds = 12, gapStart = 4, gapEnd = 8): Signal {
  const n = Math.round(seconds * sampleRate);
  const samples = new Float32Array(n);
  const ramp = 0.02;
  for (let i = 0; i < n; i++) {
    const t = i / sampleRate;
    if (t >= gapStart && t < gapEnd) continue;
    const edge = Math.min(1, Math.abs(t - gapStart) / ramp, Math.abs(t - gapEnd) / ramp);
    const w = 2 * Math.PI * 55 * t;
    samples[i] =
      (edge * 0.4 * (Math.sin(w) + 0.5 * Math.sin(2 * w) + 0.25 * Math.sin(3 * w))) / 1.75;
  }
  return { samples, sampleRate };
}

/** A small piece: bass drone, kick clicks on the beat, and a pentatonic melody. */
export function mixedPiece(sampleRate = 44100, seconds = 16): Signal {
  const drone = droneWithGap(sampleRate, seconds, seconds + 1, seconds + 2).samples;
  const clicks = clickTrack(sampleRate, seconds, 120).samples;
  const n = drone.length;
  const samples = new Float32Array(n);
  const scale = [261.63, 293.66, 329.63, 392.0, 440.0, 523.25];
  const rng = createRng(16);
  const notes = Array.from({ length: Math.ceil(seconds * 2) }, () => rng.pick(scale));
  for (let i = 0; i < n; i++) {
    const t = i / sampleRate;
    const note = Math.floor(t * 2);
    const local = t * 2 - note;
    const env = Math.min(1, local * 20) * (1 - local) * 0.9;
    const f = notes[note] ?? 440;
    const melody = env * 0.25 * Math.sin(2 * Math.PI * f * t);
    samples[i] = 0.6 * (drone[i] ?? 0) + 0.5 * (clicks[i] ?? 0) + melody;
  }
  return { samples, sampleRate };
}

/** 16-bit PCM mono WAV. */
export function encodeWav({ samples, sampleRate }: Signal): Uint8Array {
  const data = samples.length * 2;
  const buffer = new ArrayBuffer(44 + data);
  const view = new DataView(buffer);
  const text = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
  };
  text(0, 'RIFF');
  view.setUint32(4, 36 + data, true);
  text(8, 'WAVE');
  text(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  text(36, 'data');
  view.setUint32(40, data, true);
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-1, Math.min(1, samples[i] ?? 0));
    view.setInt16(44 + i * 2, Math.round(v * 32767), true);
  }
  return new Uint8Array(buffer);
}
